{
  "name": "@wakeshift/opencode",
  "version": "1.4.56",
  "description": "Wakeshift's plugin for opencode: messages from the apps your agent watches through Wakeshift wake your opencode sessions, even while they're idle.",
  "license": "Apache-2.0",
  "homepage": "https://wakeshift.ai/docs/agents",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/wakeshift/connectors.git",
    "directory": "plugins/opencode"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "wakeshift",
    "ai-agents",
    "notifications"
  ],
  "type": "module",
  "exports": {
    ".": "./index.js",
    "./server": "./index.js"
  },
  "main": "./index.js",
  "files": [
    "index.js"
  ],
  "engines": {
    "opencode": ">=1.18.7"
  },
  "optionalDependencies": {
    "@wakeshift/connect-darwin-arm64": "1.4.56",
    "@wakeshift/connect-darwin-x64": "1.4.56",
    "@wakeshift/connect-linux-arm64": "1.4.56",
    "@wakeshift/connect-linux-x64": "1.4.56"
  },
  "bugs": {
    "url": "https://github.com/wakeshift/connectors/issues"
  }
}
